import json


def _encode_cursor(record):
    return json.dumps({'ts': record['timestamp'], 'id': record['id']})


def _decode_cursor(cursor):
    decoded = json.loads(cursor)
    return (decoded['ts'], decoded['id'])


def page(records, cursor=None, limit=10):
    if limit < 1:
        raise ValueError('limit')
    ordered = sorted(records, key=lambda x: (x['timestamp'], x['id']))
    if cursor is not None:
        last = _decode_cursor(cursor)
        ordered = [x for x in ordered if (x['timestamp'], x['id']) > last]
    items = ordered[:limit]
    next_cursor = _encode_cursor(items[-1]) if len(ordered) > limit else None
    return {'items': items, 'next_cursor': next_cursor}
